// Generated by scripts/build-pvp-stats.cjs from index.html.
const ELEMENTS={poison:{name:'Poison',icon:'☠️',color:'#80cf8a'},bleed:{name:'Bleed',icon:'🩸',color:'#ed8590'},crit:{name:'Critical',icon:'🎯',color:'#e9c480'},sunder:{name:'Sunder',icon:'🔨',color:'#d5ab81'},shield:{name:'Shield',icon:'🛡️',color:'#90bdeb'},regen:{name:'Regen',icon:'💚',color:'#89d1ac'},burn:{name:'Fire',icon:'🔥',color:'#ffa16a'},slow:{name:'Frost',icon:'❄️',color:'#8de7ff'},drain:{name:'Dark',icon:'🌑',color:'#c8a1fd'}};
const FIELDS=[['Attack','atk'],['Defense','def'],['Health','hp'],['Speed','spd'],['Strength','str'],['Agility','agi'],['Intelligence','int'],['Endurance','end'],['Charisma','cha'],['Mana','mana'],['Spell','spell']];
const isTwoHanded=o=>o?.subtype==='Two-Handed';
function setCounts(equipment= {}){const counts={};for(const k of Object.keys(ELEMENTS))counts[k]=0;for(const o of Object.values(equipment))if(o?.effect)counts[o.effect]++;return counts}
function setBonuses(counts){let b=[],v={};let add=(e,title,desc,values)=>{b.push({effect:e,title,desc:setDescription(e,values)});for(const[k,val]of Object.entries(values))v[k]=(v[k]||0)+val};
if(counts.poison>=2)add('poison','Poison Set','Stronger poison stacks',{poisonBonus:counts.poison>=3?5:2});
if(counts.bleed>=2)add('bleed','Bleed Set','Bleed damages more over time',{bleedBonus:counts.bleed>=3?5:2});
if(counts.sunder>=2)add('sunder','Sunder Set','Break enemy armor faster',{sunderBonus:counts.sunder>=3?4:2});
if(counts.crit>=2)add('crit','Critical Set','Increased critical chance',{critBonus:counts.crit>=3?14:8});
if(counts.shield>=2)add('shield','Shield Set','Gain barrier on attacks',{shieldBonus:counts.shield>=3?5:3});
if(counts.regen>=2)add('regen','Regen Set','Recover extra health each second',{regenBonus:counts.regen>=3?4:2});
if(counts.burn>=2)add('burn','Fire Set','More burn damage',{burnBonus:counts.burn>=3?4:2});
if(counts.slow>=2)add('slow','Frost Set','Slows enemy attacks',{slowBonus:counts.slow>=3?.32:.18});
if(counts.drain>=2)add('drain','Dark Set','Increased life steal',{drainBonus:counts.drain>=3?.30:.15});
return {list:b,values:v}}
function totalStats(equipment= {}){
 const equipped=isTwoHanded(equipment.weapon)?{...equipment,offhand:null}:equipment;
 const s={str:5,agi:5,int:5,end:5,cha:5,atkFlat:0,defFlat:0,hpFlat:0,spdFlat:0,manaFlat:0,spellFlat:0};
 for(const item of Object.values(equipped))if(item)for(const [,key]of FIELDS){
 const dest={atk:'atkFlat',def:'defFlat',hp:'hpFlat',spd:'spdFlat',mana:'manaFlat',spell:'spellFlat'}[key]||key;
 s[dest]+=Number(item[key])||0;
 }
 const main=equipped.weapon,off=equipped.offhand,caster=!!main&&['Staff','Wand'].includes(main.subtype);
 const counts=setCounts(equipped),sets=setBonuses(counts),speed=.78+s.agi*.032+s.spdFlat*.046;
 const weaponMult={Sword:1,Mace:.66,Bow:1.18,Daggers:1.48,'Two-Handed':.53,Staff:.72,Wand:1.20}[main?.subtype]||1;
 s.caster=caster;s.main=main;s.off=off;s.sets=sets.list;s.bonus=sets.values;s.counts=counts;
 s.maxhp=Math.round(55+s.end*12+s.hpFlat);
 s.attack=Math.round(4+s.str*1.8+s.agi*.4+s.atkFlat);
 s.defense=Math.round(1+s.end*.8+s.str*.3+s.defFlat);
 s.attacksPerSec=Math.max(.25,speed*weaponMult);
 s.crit=Math.min(65,Math.round((4+s.cha*.95+counts.crit*2+(sets.values.critBonus||0))/Math.sqrt(Math.max(1,s.attacksPerSec/1.3))));
 s.mana=caster?Math.round(20+s.int*7+s.manaFlat):0;
 s.manaRegen=caster?+(1.5+s.int*.23).toFixed(1):0;
 s.spellPower=caster?Math.round(3+s.int*1.9+s.spellFlat):0;
 s.blockChance=off?.subtype==='Shield'?Math.min(48,Math.round(13+s.end*.27+Math.max(0,off.tier||1)*.25+(main?.subtype==='Mace'?7:0))):0;
 s.blockReduction=off?.subtype==='Shield'?(main?.subtype==='Mace'?.67:.58):0;
 s.power=Math.round(s.attack*2+s.defense*4+s.maxhp*.15+s.attacksPerSec*35+s.crit*1.2+s.blockChance*2+(caster?s.spellPower*1.7:0)+sets.list.length*12);
 s.lootQuality=Math.min(10,Math.round(Math.max(0,s.cha-5)*.09*10)/10);
 return s;
}
function setDescription(effect,values){
const descriptions={poison:`+${values.poisonBonus} poison potency per tick after weapon scaling`,bleed:`+${values.bleedBonus} bleed potency per tick after weapon scaling`,sunder:`+${values.sunderBonus} armor reduction per Sunder application`,crit:`+${values.critBonus} percentage points of critical chance`,shield:`+${values.shieldBonus} barrier per attack; also boosts Shield effects`,regen:`+${values.regenBonus} health per second`,burn:`+${values.burnBonus} burn potency per tick after weapon scaling`,slow:`Enemy attack interval +${Math.round((values.slowBonus||0)*100)}% while slowed`,drain:`+${Math.round((values.drainBonus||0)*100)}% healing from Dark effects`};
return descriptions[effect]||'No active bonus';
}
export {totalStats};
